import java.util.*;

class Solution {
  public int minGroupsForValidAssignment(int[] nums) {
    Map<Integer, Integer> m = new HashMap<>();
    for (int x : nums) m.put(x, m.getOrDefault(x, 0) + 1);
    int lo = Collections.min(m.values()), ans = nums.length;
    for (int g = 1; g <= lo; g++) {
      int total = 0;
      boolean ok = true;
      for (int c : m.values()) {
        int q = (c + g) / (g + 1);
        if (q * g > c) {
          ok = false;
          break;
        }
        total += q;
      }
      if (ok) ans = Math.min(ans, total);
    }
    return ans;
  }
}
